import { BaseComponent } from '../base-component';

export default BaseComponent.extend({
    name: 'HorizontalImages',
    props: {
        images: {
            type: Array,
            required: true,
        },
        imagePadding: {
            type: Number,
            default: 0,
        },
    },
    computed: {
        maxImageWidth(): string {
            return (
                (100 - (this.images.length - 1) * this.imagePadding * 2) /
                this.images.length +
                '%'
            );
        },
    },
});